"""Registry of parcels by depot."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered parcel."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(parcel):
    """Add one parcel to the registry."""
    _ALL.append(parcel)


def find(depot):
    """Return the parcels registered under this depot."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.depot, []).append(x)
    return _BY_KEY.get(depot, [])


def describe_parcel(parcel):
    """Return a one-line description of a parcel."""
    return "%s: %s" % (parcel.depot, parcel.grams)


def group_by_depot(parcels):
    """Return a dict from depot to the list of parcels with that depot."""
    groups = {}
    for x in parcels:
        groups.setdefault(x.depot, []).append(x)
    return groups

